(* [comment removed for export] *)
Lemma x1_dt_ok : forall m3 DT mtl tl cells jt,
  1 <= mtl <= 12 -> tl <= mtl + 1 -> zlen cells = 2 ^ (mtl + 1) -> length jt = (2 * length cells)%nat ->
  x1_table_ok (x1_cells cells) tl ->
  (forall i, 0 <= i < 2 ^ tl -> exists c, nth (Z.to_nat i) cells None = Some c) ->
  u8arr usegs m3 DT [Z_to_bv 8 mtl; Z_to_bv 8 0; Z_to_bv 8 tl; Z_to_bv 8 mtl] ->
  u8arr usegs m3 (DT + 4) (ox1 jt cells) ->
  huf_dt_ok m3 DT mtl.
Proof.
