Lemma skipn_nth_cons : forall {X} (l : list X) k d, (k < length l)%nat -> skipn k l = nth k l d :: skipn (S k) l.
Proof.
  intros X l. induction l as [|a l IH]; intros k d L; [cbn in L; lia|].
  destruct k as [|k]; [reflexivity|]. cbn in L |- *. apply IH. lia.
Qed.

Lemma rw_cells_nth : forall segs m A cs k d, rw_cells segs m A cs -> (k < length cs)%nat ->
  rw_cells segs m (A + Z.of_nat (cells_size (firstn k cs))) [nth k cs d].
Proof.
  intros segs m A cs k d H L.
  rewrite <- (firstn_skipn k cs) in H.
  apply (proj1 (rw_cells_app' segs m A (firstn k cs) (skipn k cs))) in H. destruct H as [_ H].
  rewrite (skipn_nth_cons cs k d L) in H.
  apply (proj1 (rw_cells_app' segs m _ [nth k cs d] (skipn (S k) cs))) in H. exact (proj1 H).
Qed.

Lemma mtl_byte : forall mtl, 1 <= mtl <= 12 -> Z.land (mtl * 0x01000001) 255 = mtl.
Proof.
  intros mtl H.
  assert (mtl = 1 \/ mtl = 2 \/ mtl = 3 \/ mtl = 4 \/ mtl = 5 \/ mtl = 6 \/ mtl = 7 \/ mtl = 8 \/ mtl = 9 \/ mtl = 10 \/ mtl = 11 \/ mtl = 12) as C by lia.
  repeat destruct C as [C|C]; subst; vm_compute; reflexivity.
Qed.

Section CANSEC. Context {rc : runConstT}.
Section TOP.
  Variables (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32).
  Variables (m : fmem) (DT W S mtl lo : Z) (src : list Z).
  Notation SP := (bv_unsigned sp).
  Notation POST := (huf_rdt_post huf_dt_ok ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc DT W S mtl src lo m).
  Notation WALL := [(bv_unsigned sp - HUF_RDT_STACK, bv_unsigned sp); (DT, DT + DTABLE_BYTES mtl); (W, W + 8704)].

  (* [comment removed for export] *)
  Lemma x1_epi : forall m' r (y1 y5 y6 y7 y8 y9 y10 y11 y12 y13 y14 y15 y16 y17 y19 y20 y21 y22 y23 y24 y25 y26 y27 y28 y29 y30 y31 : word),
    240 <= SP -> SP <= 2^47 ->
    rw_cells usegs m' (SP + -104) [C8 s11; C8 s10; C8 s9; C8 s8; C8 s7; C8 s6; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra] ->
    stk usegs m' lo (SP + -104) -> lo <= SP + -104 ->
    munch WALL m m' -> wmono usegs m m' -> mem_inv usegs m' -> 0 <= r < 2^64 -> (r < 2^64 - 119 -> huf_dt_ok m' DT mtl) ->
    evt usegs POST (MS (mkR y1 (Z_to_bv 64 (SP + -240)) gp tp y5 y6 y7 y8 y9 y10 y11 y12 y13 y14 y15 y16 y17 (Z_to_bv 64 r) y19 y20 y21 y22 y23 y24 y25 y26 y27 y28 y29 y30 y31) F (Z_to_bv 64 (PHUF_RDT_X1 + 2996)) fc None m' (seg_rom usegs)).
  Proof.
    intros m' r y1 y5 y6 y7 y8 y9 y10 y11 y12 y13 y14 y15 y16 y17 y19 y20 y21 y22 y23 y24 y25 y26 y27 y28 y29 y30 y31 SP0 SPB FR ST LOS MU WM MI R0 ROK. unfold PHUF_RDT_X1.
    repeat zstep.
    eapply stk_release in FR; [| exact ST | lia]. cbn [cells_size csize Nat.add] in FR.
    replace (SP + -104 + Z.of_nat 104) with SP in FR by lia.
    apply evt_done. unfold huf_rdt_post. do 16 eexists. split; [reflexivity|].
    unfold HUF_RDT_STACK in *. split; [exact MU|]. split; [exact WM|]. split; [exact MI|]. split; [exact FR|]. split; [exact R0|exact ROK].
  Qed.

  Lemma x1_fin : forall m2 h ws rank tl rs rs2 syms cells jt fr j8 (c1 c2 nv tv y1 y5 y6 y7 y8 y9 y10 y11 y12 y13 y14 y15 y16 y17 y18 y19 y20 y21 y22 y23 y24 y25 y26 y27 y28 y29 y30 y31 : word),
    read_stats src = Ok h -> stats_ok h -> 1 <= hs_ret h <= 129 -> Forall (fun c => 0 <= c < 256) src ->
    1 <= mtl <= 12 -> 0 < DT -> DT + 4 * (1 + 2 ^ mtl) <= lo -> lo <= SP - 4096 -> SP <= 2 ^ 47 ->
    rescale (hs_weights h) (hs_rank h) (hs_nbSymbols h) (hs_tableLog h) (Z.min (mtl + 1) 11) = Ok (ws, rank, tl) ->
    tl <= mtl + 1 ->
    rank_start_loop (Z.to_nat (tl + 1)) 0 0 rank (repeat 0 13) = Ok rs ->
    sort_loop (Z.to_nat (hs_nbSymbols h)) 0 ws rs (repeat None 256) = Ok (rs2, syms) ->
    fill_weights (Z.to_nat tl) 1 tl rank syms (repeat None (Z.to_nat (2 ^ (mtl + 1)))) (Znth 0 rank) 0 = Ok cells ->
    rw_cells usegs m2 DT [C4 (Z_to_bv 64 (mtl * 0x01000001 + tl * 65536))] ->
    u8arr usegs m2 (DT + 4) (ox1 jt cells) -> length jt = (2 * length cells)%nat ->
    rw_cells usegs m2 (SP + -240) [C8 c1; C8 c2; CB 8 j8; C8 (Z_to_bv 64 (hs_ret h))] ->
    rw_cells usegs m2 (SP + -208) fr -> cells_size fr = 96%nat ->
    rw_cells usegs m2 (SP + -112) [C4 nv] -> rw_cells usegs m2 (SP + -108) [C4 tv] ->
    rw_cells usegs m2 (SP + -104) [C8 s11; C8 s10; C8 s9; C8 s8; C8 s7; C8 s6; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra] ->
    stk usegs m2 lo (SP + -240) ->
    munch WALL m m2 -> wmono usegs m m2 -> mem_inv usegs m2 ->
    evt usegs POST (MS (mkR y1 (Z_to_bv 64 (SP + -240)) gp tp y5 y6 y7 y8 y9 y10 y11 y12 y13 y14 y15 y16 y17 y18 y19 y20
                            y21 y22 y23 y24 y25 y26 y27 y28 y29 y30 y31)
                       F (Z_to_bv 64 (PHUF_RDT_X1 + 2992)) fc None m2 (seg_rom usegs)).
  Proof.
    intros m2 h ws rank tl rs rs2 syms cells jt fr j8 c1 c2 nv tv y1 y5 y6 y7 y8 y9 y10 y11 y12 y13 y14 y15 y16 y17 y18 y19 y20 y21 y22 y23 y24 y25 y26 y27 y28 y29 y30 y31
      RS SOK RET1 SRCB MTL DT0 DTL LOS SPB RSC TLM RSL SOL FWL RDT DTC LJT FRa FRm SZF NSr TLr FRb ST MU WM MI.
    assert (P2 : 0 < 2 ^ mtl) by (apply Z.pow_pos_nonneg; lia).
    destruct (rescale_spec _ _ _ _ (Z.min (mtl + 1) 11) (WF_of_stats h SOK) ltac:(lia)) as (ws' & rank' & tl' & RSC' & WF' & TLM').
    rewrite RSC in RSC'. injection RSC' as <- <- <-.
    pose proof WF' as (TLW & LWS' & NBS' & WSR' & LRK' & RKC' & KS'). unfold FseNCount.Zlength in LWS', LRK'.
    unfold HufPure_HufStats.HUF_TABLELOG_MAX in TLW.
    destruct (x1_model_path mtl src h ws rank tl MTL SRCB RS RSC TLM ltac:(lia)) as (rs' & rs2' & syms' & cells' & RSL' & SOL' & FWL' & TOK & LC & COV).
    rewrite RSL in RSL'. injection RSL' as <-. rewrite SOL in SOL'. injection SOL' as <- <-. rewrite FWL in FWL'. injection FWL' as <-.
    unfold PHUF_RDT_X1. zstep.
    pose proof (stk_of_rw_cells usegs _ _ _ FRa) as S1. cbn [cells_size csize Nat.add] in S1.
    replace (bv_unsigned sp + -240 + Z.of_nat 32) with (bv_unsigned sp + -208) in S1 by lia.
    pose proof (stk_of_rw_cells usegs _ _ _ FRm) as S2. rewrite SZF in S2.
    replace (bv_unsigned sp + -208 + Z.of_nat 96) with (bv_unsigned sp + -112) in S2 by lia.
    pose proof (stk_of_rw_cells usegs _ _ _ NSr) as S3. cbn [cells_size csize Nat.add] in S3.
    replace (bv_unsigned sp + -112 + Z.of_nat 4) with (bv_unsigned sp + -108) in S3 by lia.
    pose proof (stk_of_rw_cells usegs _ _ _ TLr) as S4. cbn [cells_size csize Nat.add] in S4.
    replace (bv_unsigned sp + -108 + Z.of_nat 4) with (bv_unsigned sp + -104) in S4 by lia.
    pose proof (stk_merge usegs _ _ _ _ ST S1 ltac:(lia)) as S5.
    pose proof (stk_merge usegs _ _ _ _ S5 S2 ltac:(lia)) as S6.
    pose proof (stk_merge usegs _ _ _ _ S6 S3 ltac:(lia)) as S7.
    pose proof (stk_merge usegs _ _ _ _ S7 S4 ltac:(lia)) as S8.
    eapply x1_epi; [lia | lia | exact FRb | exact S8 | lia | eassumption | eassumption | eassumption | lia | intros _].
    apply (x1_dt_ok m2 DT mtl tl cells jt MTL TLM LC LJT TOK COV); [| exact DTC].
    apply u8arr_of_c4 in RDT.
    replace (mtl * 16777217 + tl * 65536) with (mtl + 256 * 0 + 65536 * tl + 16777216 * mtl) in RDT by lia.
    rewrite le4_four_bytes in RDT by lia. exact RDT.
  Qed.

  Hypothesis X396 : forall m1 h ws rank tl jrest jdt jrs jsy j80 j24 (c1 c2 tv x1 x5 x6 x7 x11 x12 x13 x16 x17 x29 x30 x31 : word),
